rules.EconomySystem:
/**
 * 经济系统（纯逻辑，无 cc）。
 * 结算顺序（固定且可测试）：
 *   1. 用战斗结果更新连胜/连败计数
 *   2. 每小关结算基础收入（当前阶段 × 每阶段金币系数）
 *   3. 计算胜利奖励（胜 +1 / 负 +0 / 平 +0）
 *   4. 计算存款利息 = min(floor(结算前余额 × 0.1), 5)
 *   5. 计算连胜/连败奖励 = min(floor(计数 / 2), 3)
 *   6. 总收入入账
 *
 * 平局处理：按现有项目规则，BattleSim 超时判 winner = -1（平局）。
 * 平局既不增加连胜也不增加连败，两个计数都保持不变。
 *
 * 所有消费（买棋子/刷新/购买经验）必须走 spend()，保证余额不为负、UI 单一数据源。
 */

export interface EconomyConfig {
  /** 每小关基础收入 = 当前阶段数 × 此系数 */
  incomePerFloor: number;
  /** Cap for stage base income, excluding interest and other bonuses. */
  incomeCap?: number;
  /** 利息上限 */
  interestCap: number;
  /** 利息比率 */
  interestRate: number;
  /** 连胜/连败奖励上限 */
  streakCap: number;
  /** 胜利奖励 */
  winBonus: number;
  /** 初始金币 */
  initialGold: number;
}

export const DEFAULT_ECONOMY_CONFIG: EconomyConfig = {
  incomePerFloor: 2,
  incomeCap: 10,
  interestCap: 5,
  interestRate: 0.1,
  streakCap: 3,
  winBonus: 1,
  initialGold: 0,
};

export interface BattleOutcome {
  /** 0 = 己方胜，1 = 敌方胜，-1 = 平局 */
  winner: number;
}

export interface SettlementBreakdown {
  floorIncome: number;
  winBonus: number;
  interest: number;
  streakBonus: number;
  total: number;
  goldBefore: number;
  goldAfter: number;
  /** 结算后的连胜数 */
  winStreak: number;
  /** 结算后的连败数 */
  loseStreak: number;
}

export class EconomySystem {
  gold: number;
  winStreak = 0;
  loseStreak = 0;

  constructor(
    public config: EconomyConfig = { ...DEFAULT_ECONOMY_CONFIG },
    initialState?: {
      gold: number;
      winStreak: number;
      loseStreak: number;
    },
  ) {
    for (const [key, value] of Object.entries(config)) {
      if (!Number.isFinite(value) || value < 0) throw new Error(`Invalid economy config: ${key}`);
    }
    const integer = (n: number) => Number.isFinite(n) ? Math.max(0, Math.min(Number.MAX_SAFE_INTEGER, Math.floor(n))) : 0;
    this.gold = integer(initialState?.gold ?? config.initialGold);
    if (initialState) {
      this.winStreak = integer(initialState.winStreak ?? 0);
      this.loseStreak = integer(initialState.loseStreak ?? 0);
    }
  }

  /**
   * 结算一场战斗。返回明细供 UI 展示。
   * 调用方保证一场战斗只调用一次（本方法内部不防重，由状态机保证）。
   */
  settleBattle(floor: number, outcome: BattleOutcome): SettlementBreakdown {
    if (!Number.isSafeInteger(floor) || floor < 1 || ![-1, 0, 1].includes(outcome.winner)) throw new Error('Invalid settlement input');
    const floorIncome = Math.min(floor * this.config.incomePerFloor, this.config.incomeCap ?? 10);
    const projected = floorIncome + this.config.winBonus + this.config.interestCap + this.config.streakCap;
    if (!Number.isFinite(projected) || projected > Number.MAX_SAFE_INTEGER - this.gold) throw new Error('Settlement exceeds safe range');
    // 1. 先更新连胜/连败（在计算奖励之前）
    if (outcome.winner === 0) {
      this.winStreak++;
      this.loseStreak = 0;
    } else if (outcome.winner === 1) {
      this.loseStreak++;
      this.winStreak = 0;
    }
    // winner === -1（平局）：两个计数都不变

    // 2~5. 计算各项收入
    const goldBefore = this.gold;
    const winBonus = outcome.winner === 0 ? this.config.winBonus : 0;
    const interest = Math.min(
      Math.floor(goldBefore * this.config.interestRate),
      this.config.interestCap,
    );
    const streakBonus = Math.min(
      Math.floor(Math.max(this.winStreak, this.loseStreak) / 2),
      this.config.streakCap,
    );
    const total = floorIncome + winBonus + interest + streakBonus;

    // 6. 入账
    this.gold += total;

    return {
      floorIncome, winBonus, interest, streakBonus, total,
      goldBefore, goldAfter: this.gold,
      winStreak: this.winStreak, loseStreak: this.loseStreak,
    };
  }

  /** 消费金币；余额不足返回 false，成功扣除返回 true。绝不扣成负数。 */
  spend(amount: number): boolean {
    if (!Number.isFinite(amount) || !Number.isSafeInteger(this.gold) || this.gold < 0) return false;
    const n = Math.floor(amount);
    if (n <= 0) return false;
    if (this.gold < n) return false;
    this.gold -= n;
    return true;
  }

  /** 直接加金币（奖励/调试用），不做上限限制 */
  add(amount: number): void {
    if (!Number.isFinite(amount) || amount < 0 || !Number.isSafeInteger(this.gold)) return;
    this.gold = Math.min(Number.MAX_SAFE_INTEGER, this.gold + Math.floor(amount));
  }

  /** 存档快照 */
  snapshot(): { gold: number; winStreak: number; loseStreak: number } {
    return { gold: this.gold, winStreak: this.winStreak, loseStreak: this.loseStreak };
  }
}

rules.ShopConfig:
/**
 * 商店与卡池配置（纯逻辑，无 cc）。
 * - SHOP_RATES[level] = 该等级 5 个费用档的抽取概率（总和必须 100）。
 * - POOL_STOCK[cost] = 每个不同棋子的初始存量。
 * - 概率表独立配置，商店逻辑不写分支。
 */

/** 费用档位 1~5 */
export type Cost = 1 | 2 | 3 | 4 | 5;

export function validCost(value: number = 1): Cost {
  if (!Number.isInteger(value) || value < 1 || value > 5) throw new Error('Invalid unit cost');
  return value as Cost;
}

/** SHOP_RATES[level][costIndex]，costIndex 0=1费 ... 4=5费；单位 % */
export const SHOP_RATES: ReadonlyArray<ReadonlyArray<number>> = [
  [100, 0, 0, 0, 0],   // 1 级
  [100, 0, 0, 0, 0],   // 2 级
  [75, 25, 0, 0, 0],   // 3 级
  [55, 30, 15, 0, 0],  // 4 级
  [45, 33, 20, 2, 0],  // 5 级
  [30, 40, 25, 5, 0],  // 6 级
  [16, 30, 43, 10, 1], // 7 级
  [15, 20, 32, 30, 3], // 8 级
  [10, 17, 25, 33, 15],// 9 级
  [5, 10, 20, 40, 25], // 10 级
];

/** Normalize against implemented cost tiers; empty stocks still use the normal retry rule. */
export function shopCostRates(level: number, supportedCosts: readonly number[] = [1, 2, 3, 4, 5]): number[] {
  const row = SHOP_RATES[Math.max(0, Math.min(SHOP_RATES.length - 1, Math.floor(Number.isFinite(level) ? level : 1) - 1))];
  const weights = row.map((rate, i) => supportedCosts.includes(i + 1) ? rate : 0);
  const total = weights.reduce((sum, rate) => sum + rate, 0);
  return weights.map(rate => total ? rate * 100 / total : 0);
}

/** 每个不同棋子的初始存量（按费用） */
export const POOL_STOCK: Readonly<Record<Cost, number>> = {
  1: 30, 2: 25, 3: 18, 4: 10, 5: 9,
};

/** 购买价格（按费用） */
export const COST_PRICE: Readonly<Record<Cost, number>> = {
  1: 1, 2: 2, 3: 3, 4: 5, 5: 8,
};

/** One-cost units keep full combined value; upgraded higher costs lose one gold. */
export const COST_SELL: Readonly<Record<Cost, number>> = {
  1: 1, 2: 2, 3: 3, 4: 5, 5: 8,
};

export function sellPrice(cost: Cost, star: number): number {
  const rank = Math.max(1, Math.min(3, Math.floor(Number.isFinite(star) ? star : 1)));
  return COST_SELL[validCost(cost)] * 3 ** (rank - 1) - (cost > 1 && rank > 1 ? 1 : 0);
}

/** 商店格子数 */
export const SHOP_SLOTS = 5;

/** 备战席格子数（可通过 SAVE 配置修改的默认值） */
export const DEFAULT_BENCH_SLOTS = 9;

/** 升星合成所需同名棋子数 */
export const MERGE_COUNT = 3;

/** 校验所有等级概率总和为 100 */
export function validateRates(): string[] {
  const errors: string[] = [];
  for (let lv = 1; lv <= SHOP_RATES.length; lv++) {
    const row = SHOP_RATES[lv - 1];
    const sum = row.reduce((a, b) => a + b, 0);
    if (sum !== 100) errors.push(`level ${lv}: rates sum ${sum} != 100`);
  }
  return errors;
}

rules.LevelSystem:
/**
 * 等级与经验系统（纯逻辑，无 cc）。
 * - 初始 1 级，上限 10 级。
 * - 每回合战斗结束 +2 经验。
 * - 备战期可单次花费 4 金币购买 4 经验。
 * - 升级表：2→3 需 2，3→4 需 6，4→5 需 10，5→6 需 20，6→7 需 36，7→8 需 56，8→9 需 68，9→10 需 68。
 * - 支持一次奖励连续升级；剩余经验保留。
 * - 当前等级 = 上阵棋子数上限；降级不会发生；升级不删除已有棋子（超员提示由调用方处理）。
 */

export const MAX_LEVEL = 10;
/** 每回合战斗结束后获得的经验 */
export const EXP_PER_BATTLE = 2;
/** One preparation-phase purchase exchanges four gold for four experience. */
export const EXP_PURCHASE = { gold: 4, exp: 4 } as const;

/** level → 升到下一级所需经验；索引 1 = 1→2 = 2 ... 索引 9 = 9→10 = 68 */
export const LEVEL_UP_EXP: ReadonlyArray<number> = [
  2,  // 1 → 2
  2,  // 2 → 3
  6,  // 3 → 4
  10, // 4 → 5
  20, // 5 → 6
  36, // 6 → 7
  56, // 7 → 8
  68, // 8 → 9
  68, // 9 → 10
];

export interface LevelUpEvent {
  from: number;
  to: number;
}

export class LevelSystem {
  level: number;
  /** 当前等级内已积累、尚未消费的经验 */
  exp: number;

  constructor(initialState?: { level: number; exp: number }) {
    this.level = Number.isFinite(initialState?.level) ? Math.floor(initialState.level) : 1;
    this.exp = Number.isFinite(initialState?.exp) ? Math.max(0, Math.min(Number.MAX_SAFE_INTEGER, Math.floor(initialState.exp))) : 0;
    if (this.level < 1) this.level = 1;
    if (this.level > MAX_LEVEL) this.level = MAX_LEVEL;
  }

  /** 当前等级升下一级所需经验；10 级返回 Infinity */
  expToNext(): number {
    if (this.level >= MAX_LEVEL) return Infinity;
    return LEVEL_UP_EXP[this.level - 1];
  }

  /** 上阵棋子数上限 = 当前等级 */
  get unitCap(): number {
    return this.level;
  }

  /**
   * 增加经验并自动连续升级。
   * 返回升级路径（如 1→2→3 则 [{from:1,to:2},{from:2,to:3}]）。
   */
  addExp(amount: number): LevelUpEvent[] {
    if (!Number.isFinite(amount) || amount <= 0) return [];
    this.exp = Math.min(Number.MAX_SAFE_INTEGER, this.exp + Math.floor(amount));
    const ups: LevelUpEvent[] = [];
    while (this.level < MAX_LEVEL && this.exp >= this.expToNext()) {
      const need = this.expToNext();
      this.exp -= need;
      const from = this.level;
      this.level++;
      ups.push({ from: from, to: this.level });
    }
    // 10 级时经验封顶不再累积意义，但保留数值不丢（供调试）
    return ups;
  }

  /** 存档快照 */
  snapshot(): { level: number; exp: number } {
    return { level: this.level, exp: this.exp };
  }
}

rules.ShopSystem:
/**
 * 商店系统（纯逻辑，无 cc）。
 * - 5 格商店：每格先按等级抽费用、再从卡池抽棋子。
 * - 对当前有库存且等级允许的费用档归一化抽取；可抽库存耗尽才显示空位。
 * - refresh：扣 2 金币 + 返还未购买的棋子到卡池。
 * - 抽到商品即预留卡池；buy 只转移预留卡，避免重复扣池。
 * - sell：棋子移除 + 返还合成所消耗的基础卡数量。
 * - 调用方允许准备 / 战斗阶段操作，当前参战单位由独立模拟器保存。
 */

import { Rng } from './Rng';
import { CardPool } from './CardPool';
import { OwnedUnits } from './OwnedUnits';
import { EconomySystem } from './EconomySystem';
import { shopCostRates, SHOP_SLOTS, COST_PRICE, Cost, sellPrice } from './ShopConfig';
import { UnitConfigData } from './ConfigManager';

export const REFRESH_COST = 2;

export interface ShopSlot {
  unitId: string | null;
}

export type ShopError =
  | 'not_enough_gold'
  | 'pool_empty'
  | 'bench_full'
  | 'slot_empty'
  | 'fighting';

export class ShopSystem {
  slots: ShopSlot[] = [];
  locked = false;

  constructor(
    private pool: CardPool,
    private owned: OwnedUnits,
    private economy: EconomySystem,
    private unitConfigs: Map<string, UnitConfigData>,
    private rng: Rng,
    private getLevel: () => number,
    private benchSlots: number,
    initialState?: ShopSlot[],
    initialStateReserved = true,
  ) {
    if (initialState && initialState.length === SHOP_SLOTS) {
      this.slots = initialState.map(s => {
        const id = s.unitId;
        if (!id || !this.unitConfigs.has(id)) return { unitId: null };
        // 旧版商品未预留库存；只在首次恢复时扣一次。
        return { unitId: (initialStateReserved || this.pool.take(id)) ? id : null };
      });
    } else {
      this.reroll(); // 初始免费生成
    }
  }

  /** 按当前等级抽一个费用档 */
  costRates(level = this.getLevel()): number[] {
    const costs = Array.from(this.unitConfigs.keys()).filter(id => this.pool.count(id) > 0)
      .map(id => this.pool.costOfUnit(id));
    return shopCostRates(level, costs);
  }

  /** RunSession assigns a fresh, independently derived stream for each complete roll. */
  setRollRng(rng: Rng): void { this.rng = rng; }

  private rollCost(level: number): Cost | null {
    const weights = this.costRates(level);
    const total = weights.reduce((sum, rate) => sum + rate, 0);
    if (!total) return null;
    const r = this.rng.next() * total;
    let acc = 0;
    for (let i = 0; i < weights.length; i++) {
      acc += weights[i];
      if (r < acc) return (i + 1) as Cost;
    }
    return (weights.findIndex(rate => rate > 0) + 1) as Cost;
  }

  /** Conditioning on available tiers is equivalent to retrying without a cutoff. */
  private rollOne(): ShopSlot {
    if (this.pool.isEmpty()) return { unitId: null };
    const cost = this.rollCost(this.getLevel());
    if (cost === null) return { unitId: null };
    const id = this.pool.pickByCost(cost, this.rng);
    if (id && this.pool.take(id)) return { unitId: id };
    return { unitId: null };
  }

  /** 刷新 5 格（内部生成，不扣钱） */
  private reroll(): void {
    this.slots = [];
    for (let i = 0; i < SHOP_SLOTS; i++) {
      this.slots.push(this.rollOne());
    }
  }

  /**
   * 手动刷新：扣金币 + 返还未购买棋子。
   * 返回 null = 成功；否则返回错误码。
   */
  refresh(): ShopError | null {
    if (!this.economy.spend(REFRESH_COST)) return 'not_enough_gold';
    this.returnUnbought();
    this.reroll();
    return null;
  }

  /** 下一轮免费更换商品，也用于返还上一轮未购买的预留卡。 */
  nextRound(): void {
    if (this.locked) return;
    this.returnUnbought();
    this.reroll();
  }

  /** 返还未购买的商店棋子到卡池（关闭/重开时也调用） */
  returnUnbought(): void {
    for (const s of this.slots) {
      if (s.unitId) {
        this.pool.give(s.unitId);
        s.unitId = null;
      }
    }
  }

  /**
   * 购买指定格。
   * 返回 null = 成功（棋子进备战席或直接合并）；否则返回错误码。
   */
  buy(slotIndex: number): { error?: ShopError; mergedUid?: number; uid?: number } {
    const s = this.slots[slotIndex];
    if (!s || !s.unitId) return { error: 'slot_empty' };
    const unitId = s.unitId;
    const price = COST_PRICE[this.pool.costOfUnit(unitId)];

    if (!Number.isSafeInteger(this.economy.gold) || this.economy.gold < price) return { error: 'not_enough_gold' };

    // 备战席满：若该购买能直接完成合并则放行，否则拒绝
    const benchFree = this.owned.inBench().length < this.benchSlots;
    if (!benchFree) {
      const same = this.owned.all().filter(u => u.unitId === unitId && u.star === 1).length;
      if (same + 1 < 3) return { error: 'bench_full' };
      // 商品已预留；满席时临时添加，随后立刻合并释放位置。
      if (!this.economy.spend(price)) return { error: 'not_enough_gold' };
      let merged;
      try {
        merged = this.owned.transaction(() => {
          this.owned.forceAdd(unitId);
          const result = this.owned.tryMerge(unitId);
          if (!result || this.owned.inBench().some(u => u.y < 0)) throw new Error('Merge did not release temporary slot');
          return result;
        });
      } catch { this.economy.add(price); return { error: 'bench_full' }; }
      s.unitId = null;
      return { mergedUid: merged!.uid };
    }

    // 正常购买
    if (!this.economy.spend(price)) return { error: 'not_enough_gold' };
    let added;
    try {
      added = this.owned.transaction(() => {
        const result = this.owned.addToBench(unitId, this.benchSlots, -1, 1);
        if (!result) throw new Error('Bench full');
        return result;
      });
    } catch { this.economy.add(price); return { error: 'bench_full' }; }
    if (!added) {
      // 理论不可达（已检查 benchFree）
      this.economy.add(price);
      return { error: 'bench_full' };
    }
    s.unitId = null;
    return { uid: added.uid };
  }

  /** 出售：移除棋子 + 返还卡池 + 加金币。调用方限制战斗期间只出售备战棋子。 */
  sell(uid: number): { gold: number } | null {
    const u = this.owned.get(uid);
    if (!u) return null;
    const cost = this.pool.costOfUnit(u.unitId);
    const gold = sellPrice(cost, u.star);
    this.owned.remove(uid);
    for (let i = 0; i < 3 ** (u.star - 1); i++) this.pool.give(u.unitId);
    this.economy.add(gold);
    return { gold };
  }

  /** 存档快照 */
  snapshot(): ShopSlot[] {
    return this.slots.map(s => ({ ...s }));
  }
}

rules.CardPool:
/**
 * 全局共享卡池（纯逻辑，无 cc）。
 * - 按棋子 id 计数；初始存量按费用从 POOL_STOCK 取。
 * - 抽取/购买共用同一份状态；不允许负数；不允许同一张重复扣/还。
 * - 单机 PvE 的"全局"= 当前单局的共享池。
 */

import { Rng } from './Rng';
import { Cost, POOL_STOCK, validCost } from './ShopConfig';
import { UnitConfigData } from './ConfigManager';

export class CardPool {
  /** unitId → 剩余张数 */
  private stock: Map<string, number> = new Map();
  /** unitId → cost（冗余缓存，避免每次查配置） */
  private costOf: Map<string, Cost> = new Map();

  constructor(
    unitConfigs: UnitConfigData[],
    initialState?: Record<string, number>,
  ) {
    for (const u of unitConfigs) {
      const cost = validCost(u.cost ?? 1);
      this.costOf.set(u.id, cost);
      const n = initialState?.[u.id] ?? POOL_STOCK[cost];
      this.stock.set(u.id, Number.isFinite(n) ? Math.max(0, Math.min(POOL_STOCK[cost], Math.floor(n))) : 0);
    }
  }

  /** 剩余张数；未知棋子返回 0 */
  count(unitId: string): number {
    return this.stock.get(unitId) ?? 0;
  }

  /** 整池剩余总数 */
  total(): number {
    let n = 0;
    for (const v of this.stock.values()) n += v;
    return n;
  }

  costOfUnit(unitId: string): Cost {
    return this.costOf.get(unitId) ?? 1;
  }

  /**
   * 按费用档随机抽一个还有存量的棋子 id；该档全空返回 null。
   * 调用方负责对空档重新掷费用；整池全空时上层显示空位。
   */
  pickByCost(cost: Cost, rng: Rng): string | null {
    const ids: string[] = [];
    for (const [id, n] of this.stock) {
      if (n > 0 && this.costOf.get(id) === cost) ids.push(id);
    }
    if (ids.length === 0) return null;
    // 确定性遍历（Map 插入序 = 配置序），rng 决定选中项
    return ids[rng.int(0, ids.length - 1)];
  }

  /** 是否还有任何棋子可抽 */
  isEmpty(): boolean {
    for (const n of this.stock.values()) if (n > 0) return false;
    return true;
  }

  /** 扣 1 张；不足返回 false（防负数） */
  take(unitId: string): boolean {
    const n = this.stock.get(unitId) ?? 0;
    if (n <= 0) return false;
    this.stock.set(unitId, n - 1);
    return true;
  }

  /** 还 1 张；防重复由调用方保证（本方法只防超额：不超过初始存量） */
  give(unitId: string): boolean {
    const n = this.stock.get(unitId) ?? 0;
    const cost = this.costOf.get(unitId);
    if (cost === undefined) return false;
    const max = POOL_STOCK[cost];
    if (n >= max) return false; // 超过初始存量视为重复返还，拒绝
    this.stock.set(unitId, n + 1);
    return true;
  }

  /** 存档快照 */
  snapshot(): Record<string, number> {
    const out: Record<string, number> = {};
    for (const [k, v] of this.stock) out[k] = v;
    return out;
  }
}
